// ─── GLOBAL ENRICHMENT ────────────────────────────────────────
// Normalize all incoming events to the Constellation standard schema

const raw = $input.first().json;
const now = new Date().toISOString();

// Validate required fields
const required = ['source', 'event_type', 'severity', 'timestamp', 'raw_data'];
const missing = required.filter(f => !raw[f]);
if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Normalize severity to 1–5 scale
const severityMap = {
  critical: 5, high: 4, medium: 3, low: 2, info: 1,
  CRITICAL: 5, HIGH: 4, MEDIUM: 3, LOW: 2, INFO: 1,
  '5': 5, '4': 4, '3': 3, '2': 2, '1': 1
};
const severityScore = severityMap[raw.severity] || 3;

// Route mapping: event_type → target agent webhook path
const routeMap = {
  // Blue Team
  siem_alert: 'blue-team/siem-enrichment',
  ioc_feed: 'blue-team/ioc-ingestion',
  threat_hunt: 'blue-team/threat-hunt',
  // IAM
  user_termination: 'iam/offboarding',
  login_anomaly: 'iam/anomaly-detector',
  mfa_gap: 'iam/mfa-enforcer',
  pam_review: 'iam/pam-review',
  // GRC
  audit_trigger: 'grc/audit-scheduler',
  risk_submission: 'grc/risk-register',
  policy_publish: 'grc/policy-tracker',
  vendor_onboard: 'grc/vendor-risk',
  data_breach: 'grc/gdpr-breach',
  // Vuln Mgmt
  scanner_result: 'vuln-mgmt/aggregator',
  patch_release: 'vuln-mgmt/patch-tuesday',
  zero_day: 'vuln-mgmt/zeroday-warroom',
  sla_breach: 'vuln-mgmt/sla-alerter',
  // Cloud
  cloud_finding: 'cloud/cspm-manager',
  image_push: 'cloud/container-gate',
  iac_commit: 'cloud/iac-gate',
  // Network
  dns_anomaly: 'network/dns-anomaly',
  credential_breach: 'network/dark-web-monitor',
  vpn_anomaly: 'network/vpn-anomaly',
  // Endpoint
  edr_alert: 'endpoint/edr-enrichment',
  malware_hash: 'endpoint/hash-blocker',
  usb_event: 'endpoint/usb-policy',
  // Threat Intel
  intel_brief: 'threat-intel/daily-brief',
  ioc_malware: 'threat-intel/ioc-processor',
  brand_alert: 'threat-intel/brand-monitor',
  // DevSecOps
  code_push: 'devsecops/secret-scanner',
  pr_created: 'devsecops/sast-dast-gate',
  dep_vuln: 'devsecops/dep-sla-monitor',
  // DFIR
  incident_declared: 'dfir/evidence-logger',
  // Awareness
  phish_result: 'awareness/phishing-tracker',
  training_gap: 'awareness/training-compliance',
};

const targetAgent = routeMap[raw.event_type];
if (!targetAgent) {
  return [{ json: { ...raw, _routing_error: true, _error: `Unknown event_type: ${raw.event_type}`, _received_at: now }}];
}

// Build normalized Constellation Event Object
return [{
  json: {
    // Routing
    _constellation_event_id: `CE-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
    _received_at: now,
    _target_agent: targetAgent,
    _routing_error: false,
    // Source data
    source: raw.source,
    event_type: raw.event_type,
    severity: raw.severity,
    severity_score: severityScore,
    timestamp: raw.timestamp,
    raw_data: raw.raw_data,
    // Optional enrichment fields (populated by subsequent nodes)
    asset_context: raw.asset_context || null,
    user_context: raw.user_context || null,
    geo_context: raw.geo_context || null,
    confidence_score: null,
    risk_level: null,
    // Pass-through any custom fields
    ...(raw.metadata && { metadata: raw.metadata }),
  }
}];

// ─── GLOBAL CONFIDENCE ENGINE ─────────────────────────────────
// Computes a preliminary confidence score BEFORE routing to agents.
// Agents will refine this with domain-specific signals.

const event = $input.first().json;

// Signal 1: Source reliability (known trusted sources score higher)
const trustedSources = ['wazuh', 'splunk', 'crowdstrike', 'qualys', 'nessus',
  'github', 'okta', 'active_directory', 'aws_securityhub', 'azure_defender'];
const sourceScore = trustedSources.includes(event.source?.toLowerCase()) ? 90 : 65;

// Signal 2: Data completeness (how many raw_data fields are populated)
const rawDataKeys = Object.keys(event.raw_data || {});
const completenessScore = Math.min(100, (rawDataKeys.length / 5) * 100);

// Signal 3: Severity contributes to urgency, not confidence
// We use a base confidence that agents will refine
const baseConfidence = Math.round(
  (sourceScore * 0.6) + (completenessScore * 0.4)
);

// Apply risk level based on severity score
let riskLevel = 'Low';
if (event.severity_score >= 5) riskLevel = 'Critical';
else if (event.severity_score >= 4) riskLevel = 'High';
else if (event.severity_score >= 3) riskLevel = 'Medium';

// Safety gate: Critical risk always requires human review
const requiresHumanGate = (riskLevel === 'Critical' || riskLevel === 'High');

return [{
  json: {
    ...event,
    confidence_score: baseConfidence,
    risk_level: riskLevel,
    requires_human_gate: requiresHumanGate,
    _confidence_breakdown: {
      source_reliability: sourceScore,
      data_completeness: Math.round(completenessScore),
      base_confidence: baseConfidence
    }
  }
}];
